import {POWER_SOURCES,generationKey} from './power-accounting.js?v=building-blocks-1';
export const HISTORY_LIMIT=1200;
export const METRICS={powerGenerated:['Domestic electricity supplied','energy units / month'],powerImported:['Electricity imported','energy units / month'],powerExported:['Electricity exported','energy units / month'],powerServed:['Electricity delivered locally','energy units / month'],...Object.fromEntries(Object.entries(POWER_SOURCES).map(([key,name])=>[generationKey(key),[name+' output','energy units / month']])),youthEducation:['Young residents education','EQ'],adultEducation:['Adult education','EQ'],garbageGenerated:['Garbage generated (recorded)','units / month'],garbageImported:['Garbage imported','units / month'],garbageRecycled:['Garbage recycled','units / month'],garbageIncinerated:['Garbage incinerated','units / month'],garbageLandfilled:['Garbage landfilled','units / month'],garbageExported:['Garbage exported','units / month'],garbageUncollected:['Uncollected garbage','units'],population:['Residents','people'],funds:['Treasury','§'],income:['Revenue','§ / month'],expenses:['Operating expenses','§ / month'],aura:['Approval / aura','0–100'],pollution:['Air pollution','0–100'],waterPollution:['Water pollution','0–100'],crime:['Crime','0–100'],education:['Education','EQ'],lifeExpectancy:['Life expectancy','years'],landValue:['Land value','0–100'],traffic:['Average road traffic','vehicles / tile'],commuters:['Workers with a commute','people'],commercialJobs:['Commercial job capacity','jobs'],industrialJobs:['Industrial job capacity','jobs'],powerCapacity:['Domestic power capacity','units'],waterCapacity:['Water capacity','units'],wasteProduction:['Garbage generated','units / month']};
export function reportSnapshot(c){const s=c.stats,roads=c.tiles.filter(t=>t.type==='road');return{youthEducation:s.youthEducation,adultEducation:s.adultEducation,aura:s.aura,waterPollution:c.tiles.reduce((v,t)=>v+t.waterPollution,0)/c.tiles.length,traffic:roads.length?roads.reduce((v,t)=>v+t.traffic,0)/roads.length:0,commuters:s.commuters-s.unemployed,commercialJobs:s.commercialJobs,industrialJobs:s.industrialJobs,powerCapacity:s.powerCapacity,waterCapacity:s.waterCapacity,wasteProduction:s.wasteProduction};}
export function historyWindow(c,years){if(![1,10,100].includes(years))throw Error('Choose 1, 10 or 100 years.');return c.history.filter(h=>h.month>c.month-years*12&&h.month<=c.month);}
export function metricSeries(rows,key){if(!Object.hasOwn(METRICS,key))throw Error('Unknown report metric.');const values=rows.filter(h=>Number.isFinite(h[key])).map(h=>({month:h.month,value:h[key]}));return{values,min:values.length?Math.min(...values.map(p=>p.value)):null,max:values.length?Math.max(...values.map(p=>p.value)):null};}
export function cleanHistory(rows,month){if(!Array.isArray(rows))return[];const byMonth=new Map();for(const h of rows){if(!h||!Number.isInteger(h.month)||h.month<0||h.month>month||!Number.isFinite(h.population)||!Number.isFinite(h.funds))continue;byMonth.set(h.month,Object.fromEntries(['month',...Object.keys(METRICS),'loanPayment','regionalPenalty'].filter(k=>Number.isFinite(h[k])).map(k=>[k,h[k]])));}return [...byMonth.values()].sort((a,b)=>a.month-b.month).slice(-HISTORY_LIMIT);}
